// usage: node shot.mjs <scenes-file> <outdir> [filterRegex]   env: THEMES=light,dark VIEWS=desktop,mobile USER=cust|fresh
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
const require = createRequire("/tank/nxeon-wt-lightmode/node_modules/");
const { chromium } = require("playwright");
const [, , scenesFile, OUT, filter] = process.argv;
const { scenes } = await import(scenesFile);
const tok = JSON.parse(readFileSync("/root/agent-notes/lightmode-audit/run/tokens.json", "utf8"));
const BASE = process.env.BASE ?? "http://localhost:3931";
const VIEWS = (process.env.VIEWS ?? "desktop,mobile").split(",");
const THEMES = (process.env.THEMES ?? "light,dark").split(",");
const views = { desktop: { width: 1440, height: 900, mobile: false }, mobile: { width: 390, height: 844, mobile: true } };
const browser = await chromium.launch({ args: ["--disable-gpu"] });
for (const sc of scenes) {
  if (filter && !new RegExp(filter).test(sc.name)) continue;
  for (const vt of VIEWS) for (const theme of THEMES) {
    const v = views[vt];
    const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme, reducedMotion: "reduce" });
    await ctx.addCookies([{ name: tok.cookie, value: tok[sc.user ?? "cust"], url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
    const page = await ctx.newPage();
    await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} }, theme);
    const errs = [];
    page.on("pageerror", (e) => errs.push(String(e).slice(0, 120)));
    try {
      await page.goto(BASE + sc.path, { waitUntil: "load", timeout: 180000 });
      await page.waitForTimeout(sc.wait ?? 3000);
      for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later"]) {
        const b = page.getByRole("button", { name: label, exact: true });
        if (await b.count().catch(() => 0)) await b.first().click({ timeout: 800 }).catch(() => {});
      }
      if (sc.act) { try { await sc.act(page, vt); } catch (e) { errs.push("act: " + String(e).slice(0, 100)); } await page.waitForTimeout(sc.afterAct ?? 1200); }
      const th = await page.evaluate(() => document.documentElement.getAttribute("data-theme"));
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
      await page.screenshot({ path: `${OUT}/${sc.name}-${vt}-${theme}.png`, fullPage: sc.full ?? true });
      console.log(sc.name, vt, theme, `data-theme=${th}`, overflow > 1 ? `OVERFLOW ${overflow}` : "", errs.length ? "ERR " + errs.join("|") : "");
    } catch (e) { console.log(sc.name, vt, theme, "FAIL", String(e).slice(0, 150)); }
    await ctx.close();
  }
}
await browser.close();
