// Runs in page context. Returns {lowContrast:[...], darkBlocks:[...]}
export const auditFn = () => {
  const parse = (c) => { const m = c.match(/rgba?\(([^)]+)\)/); if (!m) return null; const p = m[1].split(/[ ,\/]+/).filter(Boolean).map(Number); return { r: p[0], g: p[1], b: p[2], a: p[3] === undefined || isNaN(p[3]) ? 1 : p[3] }; };
  const lum = ({ r, g, b }) => { const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; }; return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b); };
  const comp = (top, bot) => ({ r: top.r * top.a + bot.r * (1 - top.a), g: top.g * top.a + bot.g * (1 - top.a), b: top.b * top.a + bot.b * (1 - top.a), a: 1 });
  const effBg = (el) => {
    const stack = [];
    for (let e = el; e; e = e.parentElement) {
      const cs = getComputedStyle(e);
      if (cs.backgroundImage !== "none" && /gradient|url/.test(cs.backgroundImage)) { stack.push("unknown"); break; }
      const c = parse(cs.backgroundColor);
      if (c && c.a > 0) { stack.push(c); if (c.a >= 0.99) break; }
    }
    if (stack.includes("unknown")) { const i = stack.indexOf("unknown"); if (i === 0) return null; }
    let base = { r: 255, g: 255, b: 255, a: 1 };
    for (let i = stack.length - 1; i >= 0; i--) { if (stack[i] === "unknown") return null; base = comp(stack[i], base); }
    return base;
  };
  const sel = (e) => { let s = e.tagName.toLowerCase(); const c = (e.getAttribute("class") || "").split(/\s+/).filter(Boolean).slice(0, 6).join("."); if (c) s += "." + c; return s.slice(0, 160); };
  const lowContrast = [], darkBlocks = [];
  const seen = new Set();
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let n; let count = 0;
  while ((n = walker.nextNode()) && count < 6000) {
    const t = n.textContent.trim(); if (!t || t.length < 1) continue;
    const el = n.parentElement; if (!el || seen.has(el)) continue; seen.add(el); count++;
    if (el.closest("script,style,noscript,svg")) continue;
    const r = el.getBoundingClientRect(); if (r.width < 2 || r.height < 2) continue;
    const cs = getComputedStyle(el); if (cs.visibility === "hidden" || cs.display === "none" || parseFloat(cs.opacity) === 0) continue;
    let hid = false; for (let e = el; e; e = e.parentElement) { const s = getComputedStyle(e); if (parseFloat(s.opacity) === 0 || s.display === "none" || s.visibility === "hidden") { hid = true; break; } }
    if (hid) continue;
    const fg = parse(cs.color); if (!fg) continue;
    const bg = effBg(el); if (!bg) continue;
    let eo = 1; for (let e = el; e; e = e.parentElement) eo *= parseFloat(getComputedStyle(e).opacity);
    const fgc = comp({ ...fg, a: fg.a * eo }, bg);
    const L1 = lum(fgc), L2 = lum(bg); const ratio = (Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05);
    const fs = parseFloat(cs.fontSize);
    if (ratio < 3 || (ratio < 4.5 && fs < 18)) lowContrast.push({ sel: sel(el), text: t.slice(0, 40), ratio: +ratio.toFixed(2), fs, fg: cs.color, bg: `rgb(${bg.r | 0},${bg.g | 0},${bg.b | 0})`, x: r.x | 0, y: (r.y + scrollY) | 0, island: !!el.closest(".nx-dark-island") });
  }
  // dark blocks: large elements w/ solid-ish dark bg on a light page
  for (const el of document.body.querySelectorAll("*")) {
    const r = el.getBoundingClientRect(); if (r.width * r.height < 6000) continue;
    const cs = getComputedStyle(el); const c = parse(cs.backgroundColor);
    if (!c || c.a < 0.5) continue; const b = effBg(el); if (!b) continue;
    if (lum(b) < 0.06 && !el.closest(".nx-dark-island,[class*=nx-shell-rail]")) darkBlocks.push({ sel: sel(el), area: (r.width * r.height) | 0, bg: `rgb(${b.r | 0},${b.g | 0},${b.b | 0})`, y: (r.y + scrollY) | 0 });
  }
  return { lowContrast, darkBlocks: darkBlocks.slice(0, 60) };
};
EOF
