929::root.nx-portal:not([data-theme="light"]) body {
933:html.nx-portal[data-theme="light"] body {
2145:  /* `&[data-theme="light"]`, not `html[data-theme="light"]` — this rule sits
2147:     scope), and `html[data-theme="light"] .chip-on` nested one level deeper
2148:     would compile to `:root.nx-portal html[data-theme="light"]
2156:  &[data-theme="light"] .chip-on {
3464:html[data-theme="light"] [data-badge-tone="green"]:not(.nx-dark-island *) { color: #047857; }
3465:html[data-theme="light"] .nx-badge-magenta:not(.nx-dark-island *) {
3471:html[data-theme="light"] .nx-creator-name:not(.nx-dark-island *) {

     script and components/nx/ThemeToggle.tsx) — body's own base rule above is
     a hardcoded dark literal specifically so marketing/login can't inherit a
     token-driven color, so the portal's light background has to be
     reintroduced here explicitly rather than via a token flip on `body`
     itself. */
  background-color: var(--color-bg);
  color: var(--color-slate-300);
  background-image:
    radial-gradient(920px 540px at 88% -12%, rgba(0, 80, 242, 0.07), transparent 62%),
    radial-gradient(700px 460px at 6% 108%, rgba(120, 40, 220, 0.05), transparent 66%);
}

/* ── dark islands ──────────────────────────────────────────────────────────
   The rail and the top bar stay dark in both themes. Rather than hard-coding
   colours into those two components, they re-declare the DARK token values on
   themselves, so their whole subtree — nav rows, the balance card, the search
   field, the account block — inherits dark without any of it knowing a theme
   exists. */
/* ══ The rest of the app ═════════════════════════════════════════════════
   This redesign covers the VPS panel; ~18 other files across Settings,
   Support, Directory, Migrate, Services and the game panel (which the VPS
   panel's own look was modelled on) use the SAME hand-written idiom: a card
   is `bg-[linear-gradient(180deg,rgba(10,22,48,N),rgba(2,7,20,N))]` with a
   `text-white` heading inside it, tuned only ever against a dark page. Editing
   every one of those files individually is a much larger change than this
   pass — these three rules retarget the pattern itself, wherever it appears,
   for light mode only. Dark mode does not match any of these selectors and is
   completely unaffected.

   The attribute selector matches the literal characters Tailwind puts in the
   `class` DOM attribute, which is unescaped there even though the generated
   CSS selector for the same class has to escape the brackets and commas — so
   `[class*="rgba(10,22,48"]` finds it without needing to know the exact
   opacity any given instance used. */
html[data-theme="light"] [class*="rgba(10,22,48"] {
  background-image: linear-gradient(180deg, rgba(255,255,255,.92), rgba(246,249,253,.98)) !important;
  border-color: var(--color-rim);
}
html[data-theme="light"] [class*="rgba(6,14,36"] {
  background: rgba(255,255,255,.85) !important;
}
html[data-theme="light"] [class*="rgba(4,11,30"] {
  background: #ffffff !important;
  border-color: var(--color-rim) !important;
}
/* A `text-white` heading is only ever meant as "the readable ink colour" in
   these components — never a colour chosen to sit on a saturated brand
   surface, which is what the VPS panel's own remaining `text-white` spots are
   (and why those were fixed by hand instead of matched here). Scoped to
   descendants of the two card patterns above, so nothing outside them moves. */
html[data-theme="light"] [class*="rgba(10,22,48"] [class~="text-white"],
html[data-theme="light"] [class*="rgba(6,14,36"] [class~="text-white"],
html[data-theme="light"] [class*="rgba(4,11,30"][class~="text-white"] {
  color: var(--color-tx) !important;
}

/* The exact opposite bug, same root cause: a `text-white` sitting on a
   hard-coded purple/blue gradient FILL (the VPS plan-selection step's
   "Selected" button, its "Most popular" ribbon, the storage quick-picks, the
   hosting-plan ribbon) wants literal white always — the fill never changes
   with the theme, only the token does. In dark mode that is invisible (both
   are `#fff`), but in light mode `--color-white` is deliberately flipped to
   near-black ink for ordinary headings, and this button caught that flip too:
   black text on a purple button. A handful of these spots already dodge it by
   writing `text-[#fff]` instead of `text-white` (see OrderBits.tsx); this one
   catches the ones that do not, wherever the same literal gradient is used,
   without having to hunt down every call site by hand. */
html[data-theme="light"] [class*="bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)]"][class~="text-white"] {
  color: #fff !important;
}

/* "Recommended" pill (OrderBits.tsx's RegionCard and the Fold `badge` prop —
   both copy the same literal recipe). `#8dbde8` on `rgba(10,40,96,…)` is a
   light pastel-blue on dark navy, tuned for a dark card, and neither value is
   theme-aware. In light mode the navy wash blends toward a pale blue-grey
   over the now-white card and the equally pale text all but disappears into
   it (~1.5:1 measured — WCAG wants 4.5:1 for text). Retargeted the same way
   as the rgba(10,22,48)-family patterns above: match the literal class text
   Tailwind puts in the DOM and swap in an ink-on-tint pairing that actually
   holds up on paper. Scoped to `text-[#8dbde8]` specifically — the only two
   spots that use it — so the visually-similar "+N add-ons" chip elsewhere
   (`text-[#9dbdee]`) is untouched. */
html[data-theme="light"] [class~="text-[#8dbde8]"] {
  color: #0b4faa !important;
  background: rgba(31, 99, 204, 0.12) !important;
  border-color: rgba(31, 99, 204, 0.4) !important;
}

/* Add-ons checkbox (OrderBits.tsx AddonRow): the unchecked tile is a hairline
   `border-rim-hi` / `bg-well` square, meant to read as "empty, tap to add".
   Both tokens sit too close to the card's own surface colour to read as a
   control at all — in dark mode `bg-well` (#000c1e) is nearly the same navy
   as the card behind it; in light mode the pale `border-rim-hi` measures
   ~1.6:1 against a white card, under the 3:1 WCAG floor for a UI boundary.
   Next to the checked state's solid gradient fill, "off" looked like no
   checkbox was there, not an unticked one. A real border plus a faint tint —
   in the same blue the checked state resolves to — makes "off" read as a
   control waiting to be ticked, in both themes, without competing with the
   filled "on" square beside it. Matched on the tile's own unique size+radius
   combo (no other checkbox in the app is 19px with a 5px radius) so this
   cannot bleed onto some other border-rim-hi/bg-well element. */
[class*="h-[19px]"][class*="w-[19px]"][class*="rounded-[5px]"][class~="border-rim-hi"][class~="bg-well"] {
  border-color: color-mix(in srgb, var(--color-blue) 55%, transparent) !important;
  background: color-mix(in srgb, var(--color-blue) 8%, transparent) !important;
}
/* The same subtle-wash idiom my own first pass used before it was fixed
   properly — `bg-white/[0.0N]` as a lightener calibrated for a dark card.
   One flat treatment for all of them rather than one rule per opacity: the
   original values were never trying to be precise, only subtle. */
html[data-theme="light"] [class*="bg-white/[0.0"] {
  background-color: color-mix(in srgb, var(--fg) 6%, transparent) !important;
}

/* The general form of the same fix, for every file this pass did not open.
   `text-white`/`bg-white`/`border-white` (bare, 100% opacity) are headings and
   want ink — that is what flipping the token above does. Anything with a
   slash after "white" is an OPACITY variant — `white/10`, `white/[0.04]`,
   `hover:bg-white/20` — and those want a wash relative to whatever the
   surface actually is now, not a tint of ink-through-transparency. Matched on
   the raw class attribute text, so it does not matter which prefix (hover:,
   sm:, etc.) precedes the utility. Gradient stop utilities (from-white/N,
   via-white/N, to-white/N) are not covered — those set a custom property
   rather than a plain CSS property, so there is no single declaration to
   override this way; decorative sheens, not text, so lower cost left as is. */
/* Islands are EXCLUDED at the selector, not overridden after the fact —
   `revert` does not mean "the value this same rule would have skipped", it
   rolls back to a different cascade origin entirely, so it cannot undo an
   `!important` sibling rule. `:not()` accepts a full selector list including
   descendant combinators, so this reads as "matches, and is not the island and
   is not inside one" in one step. Inside dark chrome, "white at 10% opacity on
   dark" is already correct in both themes and must stay untouched. */
html[data-theme="light"] [class*="bg-white/"]:not(.nx-dark-island, .nx-dark-island *) {
  background-color: color-mix(in srgb, var(--fg) 7%, transparent) !important;
}
html[data-theme="light"] [class*="border-white/"]:not(.nx-dark-island, .nx-dark-island *) {
  border-color: color-mix(in srgb, var(--fg) 16%, transparent) !important;
}
html[data-theme="light"] [class*="text-white/"]:not(.nx-dark-island, .nx-dark-island *) {
  color: color-mix(in srgb, var(--fg) 68%, transparent) !important;
}

/* Calendar's date/time inputs (EventModal, TaskPanel) carry a literal
   `[color-scheme:dark]` utility so their native picker icon and dropdown
   chrome read correctly against the (then only) dark theme. Left alone, that
   forces a dark-styled calendar/clock glyph onto what is now a plain white
   `.input` in light mode. Match the surface it is actually sitting on instead
   of the hardcoded scheme — `.nx-dark-island` below still wants real dark
   chrome and is excluded the same way the rules above are. */
html[data-theme="light"] [class*="color-scheme:dark"]:not(.nx-dark-island, .nx-dark-island *) {
  color-scheme: light;
}

html[data-theme="light"] .nx-dark-island {
  color-scheme: dark;

  --color-void: #00060f;
  --color-bg: #000816;
  --color-surface: #010f22;
  --color-well: #000c1e;
  --color-hover: #021428;
  --color-side: #00081a;
  --color-rim: #002049;
  --color-rim-soft: #00173b;
  --color-rim-hi: #002a5e;

  /* Missed the first time: anything inside the rail or top bar using
     bg-navy-900/whatever (the currency switcher, among others) fell through
     to the ROOT light-theme navy value — near-white — at whatever opacity the
     component asked for, over a dark header. That reads as a grey smear,
     which is exactly the reported bug. */
  --color-navy-950: #000816;
  --color-navy-900: #010f22;
  --color-navy-850: #021428;
  --color-navy-800: #00152f;
  --color-navy-700: #002049;
  --color-navy-600: #002a5e;
  --color-white: #ffffff;

  --color-brand-500: #8c3ae9;
  --color-brand-400: #a05cf0;
  --color-brand-300: #b785f2;
  --color-accent-blue: #2f7eef;
  --color-accent-cyan: #14c5e4;
  --color-cyan: #14c5e4;
  --color-blue: #2f7eef;
  --color-violet: #8c3ae9;
  --color-magenta: #d623e1;
  --color-mint: #11c88e;
  --color-amber: #efa828;
  --color-rose: #ef426c;
  --color-neon-bug: #39ff6a;

  --color-slate-50: #ffffff;
  --color-slate-100: #eaf2ff;
  --color-slate-200: #d8e6ff;
  --color-slate-300: #cbdcff;
  --color-slate-400: #93aede;
  --color-slate-500: #7f9ad0;
  --color-slate-600: #5f7cb4;
  --color-slate-700: #2b4a80;
  --color-slate-800: #001a3d;
  --color-slate-900: #00102a;
  --color-slate-950: #000816;

  --color-tx: #ffffff;
  --color-tx-body: #cbdcff;
  --color-tx-mute: #93aede;
  --color-tx-dim: #7f9ad0;
  --color-tx-faint: #5f7cb4;

  --fg: #ffffff;
  --fg-muted: #94a3b8;

  /* Islands paint an opaque ground. Their own classes are translucent
     (`bg-side/80`, `bg-bg/70`) so that the dark page shows through in dark
     mode; over a light page that same transparency let white through and made
     them read grey. This puts a solid dark plate behind them. */
  background-color: #00081a;

  /* The islands are still dark, so white is white again inside them. */
  --color-white: #ffffff;

  /* An inherited colour, not just tokens. `body` carries `text-slate-300` and
     sits OUTSIDE every island, so any element inside one that does not set its
     own colour — most headings do not — was inheriting the LIGHT ink straight
     past the island's token overrides. Restating it here gives the subtree a
     dark-theme default to inherit from. */
  color: #cbdcff;
}

/* The verify-email banner's wash (components/nx/Banners.tsx's shared `Banner`).
   Dark mode is the exact gradient that lived inline before this moved to a
   class — weighted to the accent on the left where the icon sits, fading to a
   near-solid dark tail on the right. Light mode fades to near-white instead of
   dark navy, so the banner reads as a tinted notice on the page it is
   actually sitting on rather than a dark island the light theme forgot.
   `--banner-rgb` is set per-instance (Banners.tsx), so this stays reusable for
   any accent color, not just the amber verify-email uses today. */
.nx-banner-wash {
  background: linear-gradient(96deg, rgba(var(--banner-rgb), 0.13), rgba(var(--banner-rgb), 0.05) 38%, rgba(1, 15, 34, 0.86));
}
html[data-theme="light"] .nx-banner-wash {
