/* ── white-alpha washes ────────────────────────────────────────────────────
   `bg-white/5`, `border-white/10`, `text-white/70`, `hover:bg-white/[0.04]` … are
   lighteners calibrated for a dark surface. Over white they vanish (or, worse,
   the old blanket attribute selector `[class*="bg-white/"]` also matched the
   `hover:`/`focus:`/`sm:` VARIANTS and painted them permanently — e.g. every file-tree
   row with `hover:bg-white/[0.04]` was grey at rest). Here each distinct token found in
   the sources gets one exact-token rule, with the pseudo-class/media wrapper its
   variant prefix implies, and an alpha mapped to a wash of ink instead of white. */
const waRe = /(?<![\\w:-])((?:(?:sm|md|lg|xl|hover|focus|focus-visible|focus-within|active|group-hover|disabled|peer-hover|first|last|odd|even):)*)(bg|border|text)-white\\/(\\[[0-9.]+\\]|[0-9]+)(?![\\w.\\]/])/g;
const waFound = new Map();
for (const p of SCAN) for (const f of walk(p)) {
  if (!/\\.(tsx|ts|jsx|js)$/.test(f) || /\\.test\\./.test(f)) continue;
  const src = readFileSync(f, "utf8");
  for (const m of src.matchAll(waRe)) waFound.set(m[0], { variants: m[1], util: m[2], raw: m[3] });
}
const BP = { sm: 640, md: 768, lg: 1024, xl: 1280 };
function washFor(util, op) {
  if (util === "bg") { if (op >= 0.4) return null; return `background-color: color-mix(in srgb, var(--fg) ${Math.round(2 + op * 100 * 0.6)}%, transparent)`; }
  if (util === "border") { if (op >= 0.5) return null; return `border-color: color-mix(in srgb, var(--fg) ${Math.round(Math.min(30, 6 + op * 100 * 0.8))}%, transparent)`; }
  return `color: color-mix(in srgb, var(--fg) ${Math.round(Math.min(94, 45 + op * 50))}%, transparent)`;
}
const waRules = [];
for (const [token, { variants, util, raw }] of [...waFound].sort((a, b) => a[0].localeCompare(b[0]))) {
  const op = raw.startsWith("[") ? parseFloat(raw.slice(1, -1)) : parseInt(raw, 10) / 100;
  const decl = washFor(util, op);
  if (!decl) continue;
  const parts = variants.split(":").filter(Boolean);
  let pseudo = "", pre = "", mq = null, ok = true;
  for (const v of parts) {
    if (BP[v]) mq = BP[v];
    else if (v === "hover") pseudo += ":hover";
    else if (v === "focus") pseudo += ":focus";
    else if (v === "focus-visible") pseudo += ":focus-visible";
    else if (v === "focus-within") pseudo += ":focus-within";
    else if (v === "active") pseudo += ":active";
    else if (v === "disabled") pseudo += ":disabled";
    else if (v === "group-hover") pre = ".group:hover ";
    else if (v === "peer-hover") ok = false;
    else ok = false; // first/last/odd/even: left as authored
  }
  if (!ok) continue;
  let rule = `html[data-theme="light"] ${pre}[class~="${token}"]${pseudo}${NOT} { ${decl} !important; }`;
  if (mq) rule = `@media (min-width: ${mq}px) { ${rule} }`;
  waRules.push(rule);
}
'''
s=s.replace('// The DOM carries the literal',add+'// The DOM carries the literal',1)
s=s.replace('const body = out\n  .map((o) => `html[data-theme="light"] [class~="${o.cls}"]${NOT} { ${o.rule} }`)\n  .join("\\n");','const body = out\n  .map((o) => `html[data-theme="light"] [class~="${o.cls}"]${NOT} { ${o.rule} }`)\n  .join("\\n") + "\\n\\n/* white-alpha washes */\\n" + waRules.join("\\n");')
s=s.replace('${out.length} rules (text','${out.length} literal rules + ${waRules.length} white-alpha rules (text')
