p='scripts/gen-light-literals.mjs'; s=open(p).read()
add='''
/* ── Tailwind palette remap ────────────────────────────────────────────────
   `text-red-400`, `text-emerald-300`, `text-amber-200` … (~1,700 uses in the portal)
   are Tailwind's own palette, tuned as pastel-on-dark. They compile to
   `color: var(--color-red-400)`, so re-declaring the variable in the light scope fixes
   every use, hover/variant included, with no per-class rules. Shades 100-400 map to a
   deeper shade; 500+ (solid fills, buttons) are untouched. Dark islands restore the
   stock values. */
const HUES = ["red", "rose", "amber", "emerald", "green", "sky", "cyan", "violet", "purple", "blue", "yellow", "orange", "teal", "indigo", "pink", "fuchsia", "lime"];
const themeCss = readFileSync(join(ROOT, "node_modules/tailwindcss/theme.css"), "utf8");
const stock = (h, n) => { const m = themeCss.match(new RegExp(`--color-${h}-${n}:\\\\s*([^;]+);`)); if (!m) throw new Error(`no stock ${h}-${n}`); return m[1].trim(); };
const MAP = { 100: 800, 200: 800, 300: 700, 400: 700 };
const lightDecl = [], darkDecl = [];
for (const h of HUES) for (const n of [100, 200, 300, 400]) {
  const to = h === "red" || h === "rose" ? (n === 400 ? 600 : MAP[n]) : MAP[n];
  lightDecl.push(`  --color-${h}-${n}: ${stock(h, to)};`);
  darkDecl.push(`  --color-${h}-${n}: ${stock(h, n)};`);
}
const paletteCss = `/* Tailwind palette remap (see scripts/gen-light-literals.mjs) */
:root.nx-portal[data-theme="light"] {
