const MAP = { 100: 800, 200: 800, 300: 700, 400: 700 };
const lightDecl = [], darkDecl = [];
for (const h of HUES) for (const n of [100, 200, 300, 400]) {
  const to = h === "red" || h === "rose" ? (n === 400 ? 600 : MAP[n]) : MAP[n];
  lightDecl.push(`  --color-${h}-${n}: ${stock(h, to)};`);
  darkDecl.push(`  --color-${h}-${n}: ${stock(h, n)};`);
}
const paletteCss = `/* Tailwind palette remap (see scripts/gen-light-literals.mjs) */
:root.nx-portal[data-theme="light"] {
${lightDecl.join("\\n")}
}
html[data-theme="light"] .nx-dark-island {
${darkDecl.join("\\n")}
}
`;
'''
s=s.replace('// The DOM carries the literal',add+'// The DOM carries the literal',1)
s=s.replace('+ waRules.join("\\n");','+ waRules.join("\\n") + "\\n\\n" + paletteCss;')
