#!/usr/bin/env node
/**
 * Light-theme guard for the customer portal. Fails (exit 1) when a change adds a hard-coded
 * dark-only colour that nothing retargets in light mode.
 *
 *  1. light-literals.generated.css must be current (new `text-[#..]` / `bg-[#..]` /
 *     `bg-white/N` / `hover:bg-white/N` tokens need their light counterpart generated):
 *        node scripts/gen-light-literals.mjs
 *  2. `bg-[rgba(r,g,b,…)]` with a near-black rgb must be covered by a selector in globals.css
 *     (`[class*="rgba(r,g,b"]`) or sit on a `.nx-dark-island` line (a surface that is
 *     dark in both themes).
 *  3. inline `style={{ background: "#0a…" }}` dark literals and bare `bg-black` need a
 *     `nx-dark-island` on the same line, or `light-ok` in a comment on that line.
 *
 * Rules live in docs/DOCUMENTATION.md → "Light theme rules".
 */
import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";

const ROOT = join(fileURLToPath(import.meta.url), "..", "..");
const SCAN = ["app/dashboard", "components/nx", "components/customer", "components/ui", "components/chat", "components/mods", "components/support", "components/skin-creator", "components/currency", "components/ChatWidget.tsx"];
function* walk(p) {
  const abs = join(ROOT, p);
  if (!existsSync(abs)) return;
  if (statSync(abs).isFile()) { yield abs; return; }
  for (const f of readdirSync(abs)) { if (f === "node_modules" || f.startsWith(".")) continue; yield* walk(join(p, f)); }
}
const problems = [];

try { execFileSync(process.execPath, [join(ROOT, "scripts/gen-light-literals.mjs"), "--check"], { stdio: "pipe" }); }
catch (e) { problems.push("app/light-literals.generated.css is stale — run `node scripts/gen-light-literals.mjs` and commit it."); }

const css = readFileSync(join(ROOT, "app/globals.css"), "utf8");
const covered = new Set([...css.matchAll(/class\*="rgba\((\d+,\d+,\d+)/g)].map((m) => m[1]));
for (const p of SCAN) for (const f of walk(p)) {
  if (!/\.tsx$/.test(f)) continue;
  const lines = readFileSync(f, "utf8").split("\n");
  lines.forEach((ln, i) => {
    const where = `${relative(ROOT, f)}:${i + 1}`;
    if (/nx-dark-island|light-ok/.test(ln)) return;
    for (const m of ln.matchAll(/bg-\[(?:linear-gradient\([^\]]*?)?rgba\((\d+),(\d+),(\d+)/g)) {
      const [r, g, b] = [m[1], m[2], m[3]].map(Number);
      if (Math.max(r, g, b) < 64 && !covered.has(`${r},${g},${b}`)) problems.push(`${where}: dark rgba(${r},${g},${b}) background has no light-mode override in app/globals.css (add one, or put nx-dark-island on this surface).`);
    }
    if (/style=\{\{[^}]*(background(Color)?)\s*:\s*["']#(0[0-9a-fA-F]{5}|1[0-3][0-9a-fA-F]{4})["']/.test(ln)) problems.push(`${where}: inline dark background literal — use a token or nx-dark-island.`);
    if (/(^|[ "'`])bg-black([ "'`]|$)/.test(ln)) problems.push(`${where}: bare bg-black — use a token, or nx-dark-island if the surface is dark in both themes.`);
  });
}
if (problems.length) { console.error("Light-theme check failed:\n - " + problems.join("\n - ")); process.exit(1); }
console.log("light-theme check passed");
EOF
node scripts/check-light-theme.mjs

